def get(self, name, default=None):
    """Query for an attribute description
    """
    attrs = self._v_attrs
    if attrs is None:
        attrs = self._v_attrs = {}
    attr = attrs.get(name)
    if attr is None:
        for iface in self.__iro__:
            attr = iface.direct(name)
            if attr is not None:
                attrs[name] = attr
                break
    return default if attr is None else attr

